.uv-shine {
  --c1: #0071e3;
  --c2: #8ec5ff;
  --s: 16px;
  /* tamaño */
  --k: 1;
  /* velocidad */
  --fg: #1d1d1f;
  /* texto */
  --bg: #f5f5f7;
  /* fondo */
}

.uv-shine {
  font-family: -apple-system,BlinkMacSystemFont,"SF Pro Text","Inter",system-ui,sans-serif;
  font-size: var(--s);
  font-weight: 600;
  line-height: 1;
  padding: 1em 2em;
  border: 0;
  border-radius: 999px;
  cursor: pointer;
  -webkit-tap-highlight-color: transparent;
  position: relative;
  overflow: hidden;
  color: #fff;
  background: var(--c1);
  box-shadow: 0 8px 24px -10px var(--c1);
  transition: transform .3s cubic-bezier(.25,.1,.25,1);
}

.uv-shine::after {
  content: "";
  position: absolute;
  inset: -50% auto -50% -60%;
  width: 40%;
  background: linear-gradient(90deg,transparent,rgba(255,255,255,.55),transparent);
  transform: skewX(-25deg);
  transition: left calc(0.7s / var(--k)) cubic-bezier(.25,.1,.25,1);
}

.uv-shine:hover::after {
  left: 130%;
}

.uv-shine:hover {
  transform: translateY(-2px);
}

.uv-shine:active {
  transform: scale(.97);
}

