  animation: uv-rip calc(0.7s / var(--k)) cubic-bezier(.25,.1,.25,1) forwards;
}

@keyframes uv-rip {
  to {
    transform: scale(40);
    opacity: 0;
  }
}
`;

// Interacción en JavaScript del DOM: la misma que en la pestaña JS.
// eslint-disable-next-line @typescript-eslint/no-explicit-any
function setup(el: any) {
  el.addEventListener("pointerdown",e=>{const r=el.getBoundingClientRect(),i=document.createElement("i");i.style.left=e.clientX-r.left+"px";i.style.top=e.clientY-r.top+"px";el.appendChild(i);setTimeout(()=>i.remove(),900)})
}

export default function BtnRipple() {
  const ref = useRef<HTMLDivElement>(null);

  useEffect(() => {
    const el = ref.current?.firstElementChild;
    return el ? setup(el) : undefined;
  }, []);

  return (
    <>
      <style>{css}</style>
      <div
        ref={ref} style={{
          "--c1": "#0071e3",
          "--c2": "#8ec5ff",
          "--s": "16px",
          "--k": "1",
          "--fg": "#1d1d1f",
          "--bg": "#f5f5f7",
        } as CSSProperties}
      >
        <button className="uv-ripple">Haz clic</button>
      </div>
    </>
  );
}

