.uv-glitch {
  --c1: #0071e3;
  --c2: #8ec5ff;
  --s: 16px;
  /* tamaño */
  --k: 1;
  /* velocidad */
  --fg: #1d1d1f;
  /* texto */
  --bg: #f5f5f7;
  /* fondo */
}

.uv-glitch {
  font-family: -apple-system,BlinkMacSystemFont,"SF Pro Text","Inter",system-ui,sans-serif;
  font-size: var(--s);
  font-weight: 600;
  line-height: 1;
  padding: 1em 2em;
  border: 0;
  border-radius: 999px;
  cursor: pointer;
  -webkit-tap-highlight-color: transparent;
  position: relative;
  border-radius: .4em;
  letter-spacing: .1em;
  color: var(--bg);
  background: var(--fg);
}

.uv-glitch::before,.uv-glitch::after {
  content: attr(data-t);
  position: absolute;
  inset: 0;
  display: grid;
  place-items: center;
  border-radius: inherit;
  background: var(--fg);
  opacity: 0;
}

.uv-glitch::before {
  color: var(--c1);
}

.uv-glitch::after {
  color: var(--c2);
}

.uv-glitch:hover::before {
  opacity: 1;
  animation: uv-g1 calc(0.4s / var(--k)) steps(2) infinite;
}

.uv-glitch:hover::after {
  opacity: 1;
  mix-blend-mode: screen;
  animation: uv-g2 calc(0.35s / var(--k)) steps(2) infinite;
}

@keyframes uv-g1 {
  0% {
    clip-path: inset(10% 0 60% 0);
    transform: translate(-3px,0);
  }
  50% {
    clip-path: inset(55% 0 15% 0);
    transform: translate(3px,0);
  }
  100% {
    clip-path: inset(30% 0 40% 0);
    transform: translate(-2px,0);
  }
}

@keyframes uv-g2 {
  0% {
    clip-path: inset(60% 0 10% 0);
    transform: translate(3px,0);
