.uv-swp {
  --c1: #12a36b;
  --c2: #b9f5d8;
  --s: 16px;
  /* tamaño */
  --k: 1;
  /* velocidad */
  --fg: #1d1d1f;
  /* texto */
  --bg: #f5f5f7;
  /* fondo */
}

.uv-swp {
  font-family: -apple-system,BlinkMacSystemFont,"SF Pro Text","Inter",system-ui,sans-serif;
  font-size: var(--s);
  color: var(--fg);
  -webkit-tap-highlight-color: transparent;
  position: relative;
  width: 17em;
  height: 3.6em;
  padding: .3em;
  border-radius: 999px;
  background: color-mix(in srgb,var(--fg) 7%,transparent);
  box-shadow: inset 0 0 0 1px color-mix(in srgb,var(--fg) 10%,transparent);
  user-select: none;
  touch-action: none;
  --x: 0px;
  --p: 0;
}

.uv-swp::before {
  content: "";
  position: absolute;
  left: .3em;
  top: .3em;
  bottom: .3em;
  width: calc(3em + var(--x));
  border-radius: 999px;
  background: linear-gradient(90deg,var(--c2),var(--c1));
  transition: width calc(0.5s / var(--k)) cubic-bezier(.22,1,.36,1);
}

.uv-swp .tx,.uv-swp .ok {
  position: absolute;
  inset: 0;
  display: grid;
  place-items: center;
  padding-left: 2.6em;
  font-weight: 600;
  pointer-events: none;
  transition: opacity calc(0.3s / var(--k)) cubic-bezier(.25,.1,.25,1);
