  -webkit-background-clip: text;
  background-clip: text;
  color: transparent;
  animation: uv-swp calc(2.6s / var(--k)) linear infinite;
}

.uv-swp .ok {
  opacity: 0;
  padding: 0 3.6em 0 0;
  color: #fff;
}

.uv-swp .kn {
  font: inherit;
  color: inherit;
  border: 0;
  margin: 0;
  background: none;
  cursor: pointer;
  -webkit-tap-highlight-color: transparent;
  position: relative;
  z-index: 1;
  display: grid;
  place-items: center;
