  cursor: grabbing;
}

.uv-swp.is-done .ok {
  opacity: 1;
}

.uv-swp.is-done .kn svg:first-child {
  opacity: 0;
}

.uv-swp.is-done .ck {
  opacity: 1;
  scale: 1;
}

.uv-swp .kn:focus-visible {
  outline: 2px solid var(--c1);
  outline-offset: 3px;
}

