  transition: transform calc(0.4s / var(--k)) cubic-bezier(.34,1.56,.64,1);
}

.uv-msh .m {
  position: absolute;
  inset: -40%;
  filter: blur(var(--bl));
}

.uv-msh i {
  position: absolute;
  width: 60%;
  height: 120%;
  border-radius: 50%;
  animation: uv-msh calc(7s / var(--k)) ease-in-out infinite alternate;
}

.uv-msh i:nth-child(1) {
  left: -5%;
  top: -10%;
  width: 45%;
  background: var(--c1);
}

.uv-msh i:nth-child(2) {
  right: 0;
  top: 0;
  width: 55%;
  background: color-mix(in srgb,var(--c2) 70%,#ff5ec4);
  animation-delay: calc(-2.5s / var(--k));
  animation-direction: alternate-reverse;
}

.uv-msh i:nth-child(3) {
  left: 35%;
  top: 30%;
  width: 30%;
  background: color-mix(in srgb,var(--c1) 40%,#ffd36e);
