}

.uv-msh:hover {
  transform: scale(1.04);
}

.uv-msh:hover svg {
  transform: rotate(90deg) scale(1.15);
}

.uv-msh:active {
  transform: scale(.97);
}

.uv-msh:focus-visible {
  outline: 2px solid var(--c1);
  outline-offset: 3px;
}

@keyframes uv-msh {
  0% {
    transform: translate(0,0) scale(1);
