.uvq01-stp {
  --c1: #c8102e;
  --c2: #f6f0e1;
  --s: 16px;
  /* tamaño */
  --k: 1;
  /* velocidad */
  --fg: #1d1d1f;
  /* texto */
  --bg: #f5f5f7;
  /* fondo */
}

.uvq01-stp {
  font-family: -apple-system,BlinkMacSystemFont,"SF Pro Text","Inter",system-ui,sans-serif;
  font-size: var(--s);
  color: var(--fg);
  -webkit-tap-highlight-color: transparent;
  display: inline-grid;
  justify-items: center;
  gap: 1em;
}

.uvq01-stp .fx {
  position: absolute;
  width: 0;
  height: 0;
}

.uvq01-stp .doc {
  position: relative;
  display: grid;
  gap: .6em;
  width: 13.5em;
  padding: 1.1em 1.2em 1.2em;
  border-radius: .35em;
  font-size: .88em;
  color: #3b3326;
  background: var(--c2);
  box-shadow: 0 1px 0 rgba(0,0,0,.05),0 14px 26px -16px rgba(0,0,0,.45);
}

.uvq01-stp .h,.uvq01-stp .tt {
  display: flex;
  justify-content: space-between;
  gap: 1em;
}

.uvq01-stp .h {
  font-weight: 700;
  letter-spacing: .02em;
}

.uvq01-stp .h span {
  font-family: ui-monospace,"SF Mono",SFMono-Regular,Menlo,Consolas,monospace;
  opacity: .6;
}

.uvq01-stp .ln {
  height: .38em;
  border-radius: 9px;
  background: rgba(59,51,38,.13);
}

.uvq01-stp .s {
  width: 70%;
}

.uvq01-stp .m {
  width: 48%;
}

.uvq01-stp .tt {
  padding-top: .6em;
  border-top: 1px dashed rgba(59,51,38,.32);
}

.uvq01-stp .mk {
  position: absolute;
  right: .5em;
  top: 46%;
  padding: .32em .5em .28em;
  font: 900 1.32em/1 "Arial Black","Helvetica Neue",Arial,sans-serif;
  letter-spacing: .08em;
  color: var(--c1);
  border: .14em solid currentColor;
  border-radius: .25em;
  box-shadow: inset 0 0 0 .1em var(--c2),inset 0 0 0 .2em currentColor;
  mix-blend-mode: multiply;
  filter: url(#uvq01-grit);
  opacity: 0;
  transform: translateY(-50%) rotate(-22deg) scale(1.9);
  transition: transform calc(0.3s / var(--k)) cubic-bezier(.25,.1,.25,1),opacity calc(0.3s / var(--k)) cubic-bezier(.25,.1,.25,1);
  pointer-events: none;
}

.uvq01-stp.is-on .mk {
  opacity: .92;
  transform: translateY(-50%) rotate(-12deg) scale(1);
  transition: transform calc(0.26s / var(--k)) cubic-bezier(.55,0,.9,.4),opacity calc(0.1s / var(--k)) cubic-bezier(.25,.1,.25,1);
}

.uvq01-stp.is-on .doc {
  animation: uvq01-stp-sh calc(0.32s / var(--k)) cubic-bezier(.25,.1,.25,1) calc(0.24s / var(--k));
}

.uvq01-stp .bt {
  font-family: -apple-system,BlinkMacSystemFont,"SF Pro Text","Inter",system-ui,sans-serif;
  font-size: var(--s);
  color: var(--fg);
  -webkit-tap-highlight-color: transparent;
  font: inherit;
  color: inherit;
  border: 0;
  margin: 0;
  background: none;
  cursor: pointer;
  -webkit-tap-highlight-color: transparent;
  position: relative;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: .6em;
  font-weight: 650;
  line-height: 1;
  letter-spacing: -.005em;
  white-space: nowrap;
  user-select: none;
  padding: .85em 1.5em;
  border-radius: .7em;
  color: #fff;
  background: #2b2722;
  box-shadow: inset 0 1px 0 rgba(255,255,255,.12),0 10px 20px -12px rgba(0,0,0,.6);
  transition: transform calc(0.2s / var(--k)) cubic-bezier(.34,1.56,.64,1),background calc(0.25s / var(--k)) cubic-bezier(.25,.1,.25,1);
}

.uvq01-stp .bt svg {
  width: 1.2em;
  height: 1.2em;
  transition: transform calc(0.3s / var(--k)) cubic-bezier(.34,1.56,.64,1);
}

.uvq01-stp .bt:hover svg {
  transform: translateY(-.15em) rotate(-8deg);
}

.uvq01-stp .bt:active {
  transform: scale(.96);
}

.uvq01-stp .bt:active svg {
  transform: translateY(.12em);
}

.uvq01-stp .bt[aria-pressed="true"] {
  background: var(--c1);
}

.uvq01-stp .bt:focus-visible {
  outline: 2px solid var(--c1);
  outline-offset: 3px;
}

@keyframes uvq01-stp-sh {
  0%,100% {
    transform: none;
  }
  30% {
    transform: translateY(.12em) rotate(.4deg);
  }
  60% {
    transform: translateY(-.05em) rotate(-.2deg);
  }
}

@media (prefers-reduced-motion:reduce) {
  .uvq01-stp,.uvq01-stp *,.uvq01-stp *::before,.uvq01-stp *::after {
    animation-duration: .01ms!important;
    animation-iteration-count: 1!important;
    transition-duration: .01ms!important;
  }
}

