.uvq01-cmp {
  --c1: #1f5140;
  --c2: #c9a24a;
  --s: 16px;
  /* tamaño */
  --k: 1;
  /* velocidad */
  --fg: #1d1d1f;
  /* texto */
  --bg: #f5f5f7;
  /* fondo */
}

.uvq01-cmp {
  font-family: -apple-system,BlinkMacSystemFont,"SF Pro Text","Inter",system-ui,sans-serif;
  font-size: var(--s);
  color: var(--fg);
  -webkit-tap-highlight-color: transparent;
  font: inherit;
  color: inherit;
  border: 0;
  margin: 0;
  background: none;
  cursor: pointer;
  -webkit-tap-highlight-color: transparent;
  position: relative;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: .6em;
  font-weight: 650;
  line-height: 1;
  letter-spacing: -.005em;
  white-space: nowrap;
  user-select: none;
  gap: .9em;
  padding: .6em 1.4em .6em .65em;
  border-radius: 999px;
  color: #f4ecd6;
  font-weight: 700;
  background: repeating-radial-gradient(circle at 85% 130%,transparent 0 .55em,rgba(255,255,255,.07) .55em calc(.55em + 1px)),radial-gradient(120% 140% at 20% 0%,color-mix(in srgb,var(--c1) 78%,#fff),var(--c1) 55%);
  box-shadow: inset 0 1px 0 rgba(255,255,255,.18),0 12px 24px -12px color-mix(in srgb,var(--c1) 80%,#000);
  transition: transform calc(0.3s / var(--k)) cubic-bezier(.34,1.56,.64,1);
}

.uvq01-cmp .dl {
  position: relative;
  display: block;
  width: 2.5em;
  height: 2.5em;
  border-radius: 50%;
  background: radial-gradient(circle,#f4ecd6 0 60%,transparent 61%),repeating-conic-gradient(from -1.5deg,#5a4a30 0 3deg,transparent 3deg 30deg),#f4ecd6;
  box-shadow: 0 0 0 .2em var(--c2),0 0 0 .26em color-mix(in srgb,var(--c2) 50%,#000),0 .2em .4em rgba(0,0,0,.35);
}

.uvq01-cmp .dl::after {
  content: "";
  position: absolute;
  inset: 0;
  border-radius: 50%;
  background: linear-gradient(135deg,rgba(255,255,255,.6),transparent 45%);
  pointer-events: none;
}

.uvq01-cmp .dl b {
  position: absolute;
  top: .3em;
  left: 50%;
  translate: -50% 0;
  font-size: .45em;
  font-weight: 900;
  line-height: 1;
  color: #b3261e;
}

.uvq01-cmp .nd {
  position: absolute;
  left: 50%;
  top: 50%;
  width: .36em;
  height: 1.9em;
  margin: -.95em 0 0 -.18em;
  background: linear-gradient(180deg,#d6402b 0 50%,#2c2a28 50%);
  clip-path: polygon(50% 0,100% 50%,50% 100%,0 50%);
  transform: rotate(var(--a,0deg));
}

.uvq01-cmp .nd::after {
  content: "";
  position: absolute;
  left: 50%;
  top: 50%;
  width: .2em;
  height: .2em;
  margin: -.1em;
  border-radius: 50%;
  background: var(--c2);
}

.uvq01-cmp svg {
  width: 1.1em;
  height: 1.1em;
  transition: transform calc(0.35s / var(--k)) cubic-bezier(.34,1.56,.64,1);
}

.uvq01-cmp:hover svg {
  transform: translateX(.25em);
}

.uvq01-cmp:active {
  transform: scale(.97);
}

.uvq01-cmp:focus-visible {
  outline: 2px solid var(--c1);
  outline-offset: 3px;
}

