document.querySelectorAll(".uvq01-cmp").forEach(el => {
  const nd=el.querySelector(".nd"),dl=el.querySelector(".dl");let a=-70,v=0,tg=0,raf=0,last=0;
const rm=matchMedia("(prefers-reduced-motion: reduce)");
const put=()=>nd.style.setProperty("--a",a.toFixed(2)+"deg");
const step=t=>{const dt=Math.min(32,last?t-last:16)/16;last=t;const d=((tg-a)%360+540)%360-180;v+=d*.05*dt;v*=Math.pow(.88,dt);a+=v*dt;put();if(Math.abs(d)<.15&&Math.abs(v)<.05){raf=0;last=0;return}raf=requestAnimationFrame(step)};
const go=()=>{if(rm.matches){a=tg;v=0;put();return}if(!raf){last=0;raf=requestAnimationFrame(step)}};
const aim=e=>{const r=dl.getBoundingClientRect();const x=e.clientX-(r.left+r.width/2),y=e.clientY-(r.top+r.height/2);if(Math.hypot(x,y)<4)return;tg=Math.atan2(x,-y)*180/Math.PI;go()};
const home=()=>{tg=0;go()};const east=()=>{tg=90;go()};
window.addEventListener("pointermove",aim,{passive:true});window.addEventListener("pointerdown",aim,{passive:true});
document.documentElement.addEventListener("pointerleave",home);el.addEventListener("focus",east);
put();go();
return()=>{window.removeEventListener("pointermove",aim);window.removeEventListener("pointerdown",aim);document.documentElement.removeEventListener("pointerleave",home);cancelAnimationFrame(raf)}
});

