document.querySelectorAll(".uvq01-arc").forEach(el => {
  const tg=el.querySelector(".tg"),ss=[...el.querySelectorAll(".s")],sum=el.querySelector(".sum"),tl=el.querySelector(".tl"),sr=el.querySelector(".sr");let n=0,tot=0;
const shoot=(x,y)=>{if(n>=3){tg.querySelectorAll(".ar").forEach(a=>a.remove());ss.forEach(s=>{s.textContent="-";s.classList.remove("on")});n=0;tot=0}
const r=Math.hypot(x-.5,y-.5)*2;const p=r>=1?0:10-Math.floor(r*10);
if(p){const a=document.createElement("i");a.className="ar";a.style.left=(x*100).toFixed(1)+"%";a.style.top=(y*100).toFixed(1)+"%";tg.appendChild(a)}
ss[n].textContent=String(p);ss[n].classList.add("on");n++;tot+=p;sum.textContent=String(tot);sr.textContent=p+" · "+tl.textContent+" "+tot;
el.classList.remove("is-hit");void el.offsetWidth;el.classList.add("is-hit")};
tg.addEventListener("click",e=>{if(e.detail===0){const a=Math.random()*Math.PI*2,d=Math.random()*.24;shoot(.5+Math.cos(a)*d,.5+Math.sin(a)*d);return}const r=tg.getBoundingClientRect();shoot((e.clientX-r.left)/r.width,(e.clientY-r.top)/r.height)})
});

