.uvq01-wnd {
  --c1: #ff6a13;
  --c2: #4aa3df;
  --s: 16px;
  /* tamaño */
  --k: 1;
  /* velocidad */
  --fg: #1d1d1f;
  /* texto */
  --bg: #f5f5f7;
  /* fondo */
}

.uvq01-wnd {
  font-family: -apple-system,BlinkMacSystemFont,"SF Pro Text","Inter",system-ui,sans-serif;
  font-size: var(--s);
  color: var(--fg);
  -webkit-tap-highlight-color: transparent;
  font: inherit;
  color: inherit;
  border: 0;
  margin: 0;
  background: none;
  cursor: pointer;
  -webkit-tap-highlight-color: transparent;
  position: relative;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: .6em;
  font-weight: 650;
  line-height: 1;
  letter-spacing: -.005em;
  white-space: nowrap;
  user-select: none;
  justify-content: flex-start;
  gap: 1em;
  height: 4em;
  padding: 0 .7em 0 5.3em;
  border-radius: 1.1em;
  overflow: hidden;
  color: #0f2a3d;
  font-weight: 750;
  background: radial-gradient(1.4em .6em at 72% 24%,rgba(255,255,255,.85),transparent 70%),radial-gradient(1em .5em at 80% 30%,rgba(255,255,255,.7),transparent 70%),linear-gradient(180deg,color-mix(in srgb,var(--c2) 70%,#fff) 0%,color-mix(in srgb,var(--c2) 25%,#fff) 80%,#7cbf5a 80%,#5aa346 100%);
  box-shadow: inset 0 0 0 1px rgba(15,42,61,.12),0 12px 24px -14px color-mix(in srgb,var(--c2) 70%,#000);
  transition: transform calc(0.25s / var(--k)) cubic-bezier(.34,1.56,.64,1);
}

.uvq01-wnd .po {
  position: absolute;
  left: 1.3em;
  top: .75em;
  bottom: 20%;
  width: .12em;
  border-radius: 1px;
  background: linear-gradient(90deg,#6f7882,#e6e9ec,#848c95);
}

.uvq01-wnd .sk {
  position: absolute;
  left: .05em;
  top: -.5em;
  display: flex;
  width: 2.8em;
  height: 1em;
  transform-origin: 0 50%;
  transform: rotate(var(--a,60deg)) scaleY(var(--sy,.5));
  clip-path: polygon(0 0,100% 22%,100% 78%,0 100%);
}

.uvq01-wnd .sk::after {
  content: "";
  position: absolute;
  inset: 0;
