}

.uvq01-wnd .sk i {
  flex: 1;
  background: var(--c1);
}

.uvq01-wnd .sk i:nth-child(even) {
  background: #fff;
}

.uvq01-wnd .t {
  position: relative;
}

.uvq01-wnd .kn {
  position: relative;
  margin-left: auto;
  padding: .42em .55em;
  border-radius: .5em;
  font: 700 .72em/1 ui-monospace,"SF Mono",SFMono-Regular,Menlo,Consolas,monospace;
  white-space: nowrap;
  background: rgba(255,255,255,.7);
}

.uvq01-wnd:active {
  transform: scale(.98);
}

.uvq01-wnd:focus-visible {
  outline: 2px solid var(--c1);
  outline-offset: 3px;
}

