const rm=matchMedia("(prefers-reduced-motion: reduce)");
const draw=()=>{const m=rm.matches?0:1;sk.style.setProperty("--a",((1-w)*60+Math.sin(ph)*(1.5+7*w)*m).toFixed(2)+"deg");sk.style.setProperty("--sy",(.5+.5*w+Math.sin(ph*1.7)*.05*w*m).toFixed(3));kb.textContent=String(Math.round(w*28))};
const step=t=>{const dt=Math.min(48,last?t-last:16);last=t;tg*=Math.pow(.965,dt/16);w+=(tg-w)*Math.min(1,.08*dt/16);ph+=dt*(.004+.02*w);draw();if(tg<.005&&w<.005){w=0;tg=0;draw();raf=0;last=0;return}raf=requestAnimationFrame(step)};
const go=()=>{if(!raf){last=0;raf=requestAnimationFrame(step)}};
el.addEventListener("pointermove",e=>{const now=performance.now();if(lt){const v=Math.hypot(e.clientX-lx,e.clientY-ly)/Math.max(8,now-lt);tg=Math.min(1,Math.max(tg,v/1.6))}lx=e.clientX;ly=e.clientY;lt=now;go()});
